        c.put("b", 2);
        c.put("c", 3);
        assertNull(c.get("a"), "a should have been evicted");
    }

    @Test
    void getRefreshesEntry() {
        LruCache<String, Integer> c = new LruCache<>(2);
        c.put("a", 1);
        c.put("b", 2);
        c.get("a");
        c.put("c", 3);
        assertEquals(1, c.get("a"));
    }
}

