import org.junit.jupiter.api.condition.OS;
import org.junit.jupiter.api.io.TempDir;

class PermissionsTest {

    @Test
    @DisabledOnOs(OS.WINDOWS)
    void secretFilesAreOwnerOnly(@TempDir Path dir) throws Exception {
        Path f = dir.resolve("secret");
        Permissions.writeSecret(f, "hunter2");
        assertEquals("rw-------", Permissions.describe(Files.getPosixFilePermissions(f)));
    }

    @Test
    void describeFormatsAllBits() {
        assertEquals("rwxr-x---", Permissions.describe(Permissions.parse("750")));
    }
}
